func userInitial(email string) string {
	if email == "" {
		return "?"
	}
	r := []rune(email)
	if len(r) == 0 {
		return "?"
	}
	first := r[0]
	if first >= 'a' && first <= 'z' {
		first = first - 32
	}
	return string(first)
}

